using System.Text.Json.Nodes;
using Panda.Bridge.Auth;

namespace Panda.Bridge.Tests;

/// <summary>Seam S2: the C# primitives reproduce schema/auth-vectors.json (generated by an independent Python implementation).</summary>
public class AuthCryptoTests
{
    private static readonly JsonNode Vectors = JsonNode.Parse(File.ReadAllText(RepoPaths.Schema("auth-vectors.json")))!;

    private static TheoryData<string> Cases(string section) =>
        new(Vectors[section]!.AsArray().Select(n => n!.ToJsonString()));

    public static TheoryData<string> Frames() => Cases("frame");
    public static TheoryData<string> Normalizations() => Cases("normalize");
    public static TheoryData<string> Base64Urls() => Cases("base64url");
    public static TheoryData<string> Proofs() => Cases("proofs");
    public static TheoryData<string> Negatives() => Cases("verifyNegative");
    public static TheoryData<string> Fingerprints() => Cases("fingerprint");
    public static TheoryData<string> Base32s() => Cases("base32");

    private static string S(JsonNode v, string key) => v[key]!.GetValue<string>();

    private static byte[] Nonce(JsonNode v, string key) =>
        AuthCrypto.TryDecodeBase64Url(S(v, key), 16, out var bytes) ? bytes : throw new InvalidOperationException(key);

    private static string Compute(JsonNode v) => S(v, "label") switch
    {
        "bridge" => AuthCrypto.BridgeProof(Secret(v), Nonce(v, "extNonce"), Nonce(v, "bridgeNonce"), S(v, "browserInstanceId")),
        "ext" => AuthCrypto.ExtProof(Secret(v), Nonce(v, "extNonce"), Nonce(v, "bridgeNonce"), S(v, "browserInstanceId")),
        "pair-bridge" => AuthCrypto.PairBridgeProof(S(v, "code"), Nonce(v, "extNonce"), Nonce(v, "bridgeNonce")),
        "pair-ext" => AuthCrypto.PairExtProof(S(v, "code"), Nonce(v, "extNonce"), Nonce(v, "bridgeNonce")),
        var other => throw new InvalidOperationException(other),
    };

    private static byte[] Secret(JsonNode v) =>
        AuthCrypto.TryDecodeBase64Url(S(v, "secret"), 32, out var bytes) ? bytes : throw new InvalidOperationException("secret");

    [Theory]
    [MemberData(nameof(Base32s))]
    public void Base32_matches_vector(string json)
    {
        var v = JsonNode.Parse(json)!;
        Assert.Equal(S(v, "code"), AuthCrypto.EncodeBase32(Convert.FromHexString(S(v, "bytesHex"))));
    }

    [Theory]
    [MemberData(nameof(Frames))]
    public void Frame_matches_vector(string json)
    {
        var v = JsonNode.Parse(json)!;
        var fields = v["fieldsHex"]!.AsArray().Select(f => Convert.FromHexString(f!.GetValue<string>())).ToArray();
        Assert.Equal(S(v, "frameHex"), Convert.ToHexStringLower(AuthCrypto.Frame(fields)));
    }

    [Theory]
    [MemberData(nameof(Normalizations))]
    public void Pair_code_normalization_matches_vector(string json)
    {
        var v = JsonNode.Parse(json)!;
        var expected = v["normalized"]?.GetValue<string>();
        Assert.Equal(expected is not null, AuthCrypto.TryNormalizePairCode(S(v, "input"), out var normalized));
        Assert.Equal(expected, normalized);
    }

    [Theory]
    [MemberData(nameof(Base64Urls))]
    public void Base64url_decoding_is_strict(string json)
    {
        var v = JsonNode.Parse(json)!;
        var expected = v["bytesHex"]?.GetValue<string>();
        var ok = AuthCrypto.TryDecodeBase64Url(S(v, "text"), v["length"]!.GetValue<int>(), out var bytes);
        Assert.Equal(expected is not null, ok);
        if (expected is not null)
        {
            Assert.Equal(expected, Convert.ToHexStringLower(bytes));
            Assert.Equal(S(v, "text"), AuthCrypto.EncodeBase64Url(bytes));
        }
    }

    [Theory]
    [MemberData(nameof(Proofs))]
    public void Proof_matches_vector_and_verifies(string json)
    {
        var v = JsonNode.Parse(json)!;
        var proof = Compute(v);
        Assert.Equal(S(v, "proof"), proof);
        Assert.True(AuthCrypto.Verify(proof, S(v, "proof")));
    }

    [Theory]
    [MemberData(nameof(Negatives))]
    public void Verify_rejects_wrong_proof_without_throwing(string json)
    {
        var v = JsonNode.Parse(json)!;
        Assert.False(AuthCrypto.Verify(Compute(v), S(v, "received")), S(v, "why"));
    }

    [Theory]
    [MemberData(nameof(Fingerprints))]
    public void Fingerprint_matches_vector(string json)
    {
        var v = JsonNode.Parse(json)!;
        Assert.Equal(S(v, "fingerprint"), AuthCrypto.Fingerprint(S(v, "bridgeId")));
    }

    [Fact]
    public void Proofs_reject_wrong_key_and_nonce_lengths()
    {
        var n16 = new byte[16];
        Assert.Throws<ArgumentException>(() => AuthCrypto.BridgeProof(new byte[31], n16, n16, "chrome-abcd2345"));
        Assert.Throws<ArgumentException>(() => AuthCrypto.ExtProof(new byte[32], new byte[15], n16, "chrome-abcd2345"));
        Assert.Throws<ArgumentException>(() => AuthCrypto.PairBridgeProof("not-a-code", n16, n16));
        Assert.Throws<ArgumentException>(() => AuthCrypto.PairExtProof("MRSWMZ3INFVGW3DNNZXXA4LSOM", n16, new byte[17]));
    }

    [Fact]
    public void Verify_with_null_received_is_false()
    {
        Assert.False(AuthCrypto.Verify(new string('0', 64), null));
    }
}
